/*
 * pa_oversample.h - 4x oversampling for the drive's clipping stage.
 *
 * Two cascaded 2x polyphase allpass half-band stages (the elliptic-derived design
 * of L. de Soras' HIIR; coefficients generated by custom-fw/tools/hb_design.py):
 *
 *   stage 1  44.1 -> 88.2 kHz   8 coefficients  flat to 20 kHz, images/aliases above
 *                                                24.1 kHz rejected by 99 dB
 *   stage 2  88.2 -> 176.4 kHz  3 coefficients  flat to 20 kHz, 89 dB above 68.2 kHz
 *
 * Each coefficient is one first-order allpass section in the low-rate domain,
 *     y = a * (x - y1) + x1,
 * so the whole 4x round trip costs ~28 multiplies per input sample. Float: the
 * AC791N has a single-precision FPU.
 *
 * It replaces a 1-coefficient-per-branch filter whose image rejection was ~30 dB:
 * a 3.5 kHz note through the RAT at full gain had an alias 26 dB under the note.
 *
 * The response is allpass (non-linear phase), so a clean signal that is mixed with
 * the clipped one (TS-808, Klon) must go through the same up/down path - mix them
 * at the 4x rate, before pa_os4_down().
 */
#ifndef PA_OVERSAMPLE_H
#define PA_OVERSAMPLE_H

#define PA_HB1_N 8
#define PA_HB2_N 3

typedef struct { float x1[PA_HB1_N], y1[PA_HB1_N]; } pa_hb1_t;   /* one stage-1 filter */
typedef struct { float x1[PA_HB2_N], y1[PA_HB2_N]; } pa_hb2_t;   /* one stage-2 filter */

/* upsampler: stage 1 runs once per input, stage 2 (one state, at the 2x rate) twice */
typedef struct { pa_hb1_t s1; pa_hb2_t s2; } pa_os4_up_t;
/* downsampler: stage 2 twice, stage 1 once; d2/d1 hold the odd branch's previous sample */
typedef struct { pa_hb2_t s2; pa_hb1_t s1; float d2, d1; } pa_os4_down_t;

static const float pa_hb1_c[PA_HB1_N] = {
    0.0406334609f, 0.1505051290f, 0.3007570560f, 0.4607745050f,
    0.6095243149f, 0.7385038411f, 0.8492238104f, 0.9497427837f
};
static const float pa_hb2_c[PA_HB2_N] = { 0.0702240593f, 0.2850862804f, 0.6845413589f };

/* the two polyphase branches: even coefficients -> branch 0, odd -> branch 1 */
static inline void pa_hb_branches(const float *c, int n, float *x1, float *y1,
                                  float in, float *b0, float *b1) {
    float v0 = in, v1 = in;
    for (int i = 0; i < n; i += 2) {
        float y = c[i] * (v0 - y1[i]) + x1[i];
        x1[i] = v0; y1[i] = y; v0 = y;
    }
    for (int i = 1; i < n; i += 2) {
        float y = c[i] * (v1 - y1[i]) + x1[i];
        x1[i] = v1; y1[i] = y; v1 = y;
    }
    *b0 = v0; *b1 = v1;
}

/* decimator branches: branch 0 filters the even input, branch 1 the odd one */
static inline float pa_hb_down(const float *c, int n, float *x1, float *y1,
                               float even, float odd_delayed) {
    float v0 = even, v1 = odd_delayed;
    for (int i = 0; i < n; i += 2) {
        float y = c[i] * (v0 - y1[i]) + x1[i];
        x1[i] = v0; y1[i] = y; v0 = y;
    }
    for (int i = 1; i < n; i += 2) {
        float y = c[i] * (v1 - y1[i]) + x1[i];
        x1[i] = v1; y1[i] = y; v1 = y;
    }
    return 0.5f * (v0 + v1);
}

/* 1 sample in, 4 samples out (in time order) */
static inline void pa_os4_up(pa_os4_up_t *u, float in, float out[4]) {
    float a, b;
    pa_hb_branches(pa_hb1_c, PA_HB1_N, u->s1.x1, u->s1.y1, in, &a, &b);
    pa_hb_branches(pa_hb2_c, PA_HB2_N, u->s2.x1, u->s2.y1, a, &out[0], &out[1]);
    pa_hb_branches(pa_hb2_c, PA_HB2_N, u->s2.x1, u->s2.y1, b, &out[2], &out[3]);
}

/* 4 samples in (time order), 1 sample out */
static inline float pa_os4_down(pa_os4_down_t *d, const float in[4]) {
    /* y[m] = (A0(w[2m]) + A1(w[2m-1])) / 2 on the 4x stream w = in[0..3] */
    float a = pa_hb_down(pa_hb2_c, PA_HB2_N, d->s2.x1, d->s2.y1, in[0], d->d2);
    float b = pa_hb_down(pa_hb2_c, PA_HB2_N, d->s2.x1, d->s2.y1, in[2], in[1]);
    d->d2 = in[3];
    float y = pa_hb_down(pa_hb1_c, PA_HB1_N, d->s1.x1, d->s1.y1, a, d->d1);
    d->d1 = b;
    return y;
}

/* The cheaper 2x pair (stage 1 only), used by the load governor when the audio interrupt runs too long. */
static inline void pa_os2_up(pa_os4_up_t *u, float in, float out[2]) {
    pa_hb_branches(pa_hb1_c, PA_HB1_N, u->s1.x1, u->s1.y1, in, &out[0], &out[1]);
}
static inline float pa_os2_down(pa_os4_down_t *d, const float in[2]) {
    const float y = pa_hb_down(pa_hb1_c, PA_HB1_N, d->s1.x1, d->s1.y1, in[0], d->d1);
    d->d1 = in[1];
    return y;
}

#endif /* PA_OVERSAMPLE_H */
